//! ECDSA vectors, taken from the certificate chain in `x509_vectors`.
//!
//! Each entry is one real signature: the issuer's public key, the bytes that
//! were signed, and the r and s the issuer produced.  The curve code is tested
//! against these directly, without the ASN.1 parser in between, so a failure
//! says which of the two is broken.
//!
//! Real signatures rather than generated ones because a curve implementation
//! can be wrong in ways only real inputs show -- a truncated z, a doubling
//! formula that is right only for small coordinates -- and a test written the
//! same day as the code tends to share its misconceptions.

/// One signature to check.
pub struct EcVector {
    pub name: &'static str,
    /// Curve: "P-256" or "P-384".
    pub curve: &'static str,
    /// Hash used: "sha256", "sha384" or "sha512".
    pub hash: &'static str,
    /// Uncompressed public key point of the issuer.
    pub pubkey: &'static [u8],
    /// The bytes that were signed (a TBSCertificate).
    pub signed: &'static [u8],
    /// The signature, r then s, each padded to the coordinate width.
    pub sig: &'static [u8],
}

const LEAF_PUB: &[u8] = b"04fd1d14148e23429326cf70d089d7b11e72ac3e5d595281df1cf5d625b9d67707850b8d12b12b3f40b91f7206e0ff40520a9349f8c971b07eeee0a34551184474";   // 65 bytes
const LEAF_TBS: &[u8] = b"";   // 913 bytes
